SELECT COUNT(*) AS total_eway_bills
FROM public.tbl_ewb_parta_ewb
LIMIT 100;

SELECT SUM(e.igstval) AS total_igst_collected
FROM public.tbl_ewb_parta_ewb e
WHERE e.frstat <> e.tostat;

SELECT SUM(cgstval + sgstval + igstval) AS total_tax_collected
FROM public.tbl_ewb_parta_ewb
LIMIT 100;

SELECT SUM(cgstval) AS total_cgst
FROM public.tbl_ewb_parta_ewb
LIMIT 100;

SELECT SUM(sgstval) AS total_sgst
FROM public.tbl_ewb_parta_ewb
LIMIT 100;

SELECT COUNT(DISTINCT frgstin) AS distinct_consignors
FROM public.tbl_ewb_parta_ewb
LIMIT 100;

SELECT COUNT(DISTINCT e.tostat) AS distinct_destination_states
FROM public.tbl_ewb_parta_ewb e
LIMIT 100;

SELECT SUM(e."InvVal") AS total_invoice_value
FROM public.tbl_ewb_parta_ewb e
